import { Handle, Position } from '@xyflow/react';
import './FiberDeviceNode.css';

const deviceIcons = {
  router: '🌐',
  switch: '🔌',
  olt: '📡',
  ont: '💻'
};

const deviceColors = {
  router: '#ef4444',
  switch: '#f59e0b',
  olt: '#10b981',
  ont: '#3b82f6'
};

export default function FiberDeviceNode({ data, selected }) {
  const icon = deviceIcons[data.type] || '📦';
  const color = deviceColors[data.type] || '#64748b';

  return (
    <div className={`fiber-node ${selected ? 'selected' : ''} type-${data.type}`}>
      {/* Type indicator dot */}
      <div 
        style={{
          position: 'absolute',
          top: 8,
          right: 8,
          width: 8,
          height: 8,
          borderRadius: '50%',
          background: color
        }}
      />
      
      <div className="node-icon">{icon}</div>
      <div className="node-header">{data.type.toUpperCase()}</div>
      
      <div className="node-details">
        <div className={`node-row ${!data.hostname ? 'value-empty' : ''}`}>
          <span>Host:</span>
          <strong>{data.hostname || '—'}</strong>
        </div>
        <div className={`node-row ${!data.ip ? 'value-empty' : ''}`}>
          <span>IP:</span>
          <strong>{data.ip || '—'}</strong>
        </div>
      </div>

      {/* Connection handles */}
      <Handle 
        type="target" 
        position={Position.Left} 
        style={{ background: color, borderColor: color }}
      />
      <Handle 
        type="source" 
        position={Position.Right} 
        style={{ background: color, borderColor: color }}
      />
    </div>
  );
}
